"""Client's October 2026 expertise content, with bilingual editorial layout."""
def build_expertise(bi, img, button, label, title, hero):
 def p(zh,en,cls='section-lead'): return bi('p',zh,en,f'class="{cls}"')
 def crop(name, x,y,w,h,zh,en):
  originals={'factory': 'expertise-factory-hd-20261019.lossless.webp', 'certification': 'expertise-certification-hd-20261019.lossless.webp', 'showroom': 'expertise-showroom-hd-20261019.lossless.webp', 'awards': 'expertise-awards-hd-20261019.lossless.webp'}
  if name in originals:
   return f'<div class="evidence-window evidence-original evidence-{name}">{img(originals[name],zh,en).replace(' src=', f' data-src-zh="/assets/{originals[name]}" data-src-en="/assets/expertise-{name}-en-20261019.png" src=')}</div>'
  style=f'width:{1448/w*100:.6f}%;height:auto;left:{-x/w*100:.6f}%;top:0;transform:translateY({-y/4586*100:.6f}%)'
  return f'<div class="evidence-window evidence-{name}" style="aspect-ratio:{w}/{h}"><img src="/assets/expertise-client-reference-20261019.lossless.webp" width="1448" height="4586" loading="lazy" alt="{zh}" data-alt-en="{en}" style="{style}"></div>'
 body=hero('expertise-hero','expertise-hero-20261021.jpg','OUR EXPERTISE','每一份舒适，<br>都有深厚积淀。','Expertise behind<br>every experience.','以律动技术连接设计与制造，<br>让恢复与放松，自然融入日常。','Rhythm technology, thoughtful design and precise manufacturing.<br>Bringing rest and relaxation into everyday life.','#expertise','探索品牌实力','Discover our expertise')
 body+='<section class="expertise-values section-pad" aria-label="Dynamic wellness">'+label('动态健康','DYNAMIC WELLNESS')+'<div class="expertise-value-grid">'
 icons=['<path d="M8 15c6-7 10 7 19 0M8 20c6-7 10 7 19 0M8 25c6-7 10 7 19 0"/>','<circle cx="18" cy="13" r="4"/><path d="M10 28v-2a8 8 0 0 1 16 0v2"/>','<path d="m7 17 11-9 11 9M10 15v13h16V15"/>']
 for icon,z,e in zip(icons,['精准律动','个性化舒适体验','专为居家生活设计'],['Precision in motion','Comfort, made personal','Designed for home']):
  body+='<div class="expertise-value reveal"><svg viewBox="0 0 36 36" fill="none" stroke="currentColor" stroke-width="1.1" stroke-linecap="round" aria-hidden="true">'+icon+'</svg>'+bi('h2',z,e)+'</div>'
 body+='</div></section>'
 body+='<section class="expertise-intro section-pad" id="expertise"><div class="expertise-intro-copy reveal">'+label('每一次 RHYVIA 体验背后','BEHIND EVERY RHYVIA EXPERIENCE')+title('舒适，早在你<br>落座之前开始。','Comfort begins<br>before you sit down.')+p('研究、工程、精密制造、质量控制与客户服务，构成 RHYVIA 的完整支持系统。每一个环节，共同成就一致、从容的舒适体验。','Research, engineering, precision manufacturing, quality control and customer care form the system behind RHYVIA. Each part works together to create a consistent, considered experience.')+'<div class="expertise-intro-notes"><div>'+bi('h3','从研究，到日常','From research to everyday life')+p('中国、德国与日本的研究团队和开发机构，让想法经历早期探索、反复测试，最终走向实际生产。','Research teams and development partners in China, Germany and Japan help bring ideas from early exploration through repeated testing and into production.','body-copy')+'</div><div>'+bi('h3','从制造，到感受','From precision to comfort')+p('精密制造与严谨品控相互配合，让看不见的用心，成为每一次落座时感受得到的舒适。','Precision manufacturing and careful quality control turn the work behind the scenes into comfort you can feel.','body-copy')+'</div></div>'+button('预约亲身体验','Experience RHYVIA','/experience/')+'</div><figure class="expertise-atrium reveal">'+img('expertise-atrium-20261019.lossless.webp','女性在柔和日光与悬垂织物下的躺椅上休憩，品牌氛围示意','Illustrative lifestyle scene of a woman reclining in a sunlit atrium')+'</figure></section>'
 body+='<section class="heritage-section section-pad" id="heritage"><div class="heritage-heading reveal">'+label('RHYVIA 背后的实力','THE FOUNDATION OF RHYVIA')+'<div class="heritage-heading-row">'+title('26 年创新积淀','26 years of<br>innovation.')+p('始于 2000 年。<br>让创新，回归生活的舒适。','Since 2000. <br>Innovation with everyday comfort at its heart.','heritage-aside')+'</div></div><div class="heritage-grid"><figure class="heritage-building reveal">'+'<div class="evidence-window evidence-original evidence-building">'+img('expertise-building-20261023.lossless.webp','客户提供的 CBD 大楼建筑效果图','CBD building architectural rendering supplied by the client')+'</div>'+'<figcaption>'+bi('span','CBD 家居 · 品牌积淀','CBD HOME · OUR HERITAGE')+'</figcaption></figure><div class="heritage-copy reveal">'+bi('h3','根植 CBD 家居，<br>面向更舒适的日常。','Rooted in CBD Home.<br>Created for a more comfortable everyday.')+p('RHYVIA 的核心技术源自 CBD 家居——一家创立于 2000 年的健康家居科技企业。26 年来，CBD 持续融合国际研发、智能制造、材料创新与人体设计，为日常生活带来更舒适的体验。','RHYVIA’s core technology draws on CBD Home, a wellness-focused home technology company founded in 2000. Over 26 years, CBD has brought together international research, smart manufacturing, material innovation and human-centred design.')+p('CBD 水平律动技术依托 1,000 多项产品专利、3 个国际研发中心，以及位于深圳和惠州的两大智能制造基地。','CBD’s horizontal-motion technology is backed by more than 1,000 product patents, three international R&D centres and two smart manufacturing bases in Shenzhen and Huizhou.','body-copy')+'</div></div><div class="heritage-stats reveal">'
 for num,z,e in [('26<span>+</span>','年行业经验','Years of industry experience'),('1,000<span>+</span>','项产品专利','Product patents'),('3','个国际研发中心','International R&D centres')]:
  body+='<div><strong>'+num+'</strong>'+p(z,e,'stat-label')+'</div>'
 body+='</div><div class="proof-grid">'
 for key,x,y,w,h,z,e,bz,be in [('showroom',0,2894,486,455,'品牌实力','A presence you can experience','从产品展示到面对面交流，让舒适被更多人看见与感受。','Bringing products and people together through presentation and personal experience.'),('awards',493,2894,455,455,'专业认可','Recognition through dedication','持续的产品研发与专业积累，留下品牌成长的印记。','A record of continued product development and professional commitment.'),('technology',959,2894,489,455,'技术落地','Ideas put into practice','从技术探索走向实际应用，让创新拥有更长远的视野。','Moving from exploration into application, with a long-term view of innovation.')]:
  body+='<article class="proof-card reveal">'+crop(key,x,y,w,h,z,e)+'<div>'+bi('h3',z,e)+p(bz,be,'body-copy')+'</div></article>'
 body+='</div></section>'
 body+='<section class="manufacturing-section section-pad" id="manufacturing"><div class="manufacturing-head reveal"><div>'+label('研发与制造','RESEARCH & MANUFACTURING')+title('规模之上，<br>是对细节的坚持。','Scale, with care<br>in every detail.')+'</div><div class="manufacturing-number"><strong>400,000<span>m²</span></strong>'+p('生产网络面积','Manufacturing network','stat-label')+'</div></div><figure class="factory-panorama reveal">'+crop('factory',415,3450,1002,291,'客户提供的 CBD 智能制造基地图片','CBD smart manufacturing base, from the client reference')+'</figure><div class="manufacturing-details"><div class="reveal">'+label('国际协作','INTERNATIONAL COLLABORATION')+bi('h3','中国 · 德国 · 日本','China · Germany · Japan')+p('研究团队与开发机构协同工作，将概念探索、工程开发与反复测试连接起来。','Research teams and development partners connect concept exploration, engineering development and repeated testing.','body-copy')+'</div><div class="reveal">'+label('智能制造','SMART MANUFACTURING')+bi('h3','深圳 · 惠州','Shenzhen · Huizhou')+p('两大智能制造基地，持续提升产品品质与交付能力。生产网络配备 GMP 标准设施，并采用借鉴汽车行业的质量控制流程。','Two smart manufacturing bases support product quality and delivery. The manufacturing network combines GMP-standard facilities with quality-control processes informed by the automotive industry.','body-copy')+'</div></div></section>'
 body+='<section class="certification-section section-pad"><figure class="certification-image reveal">'+crop('certification',31,3751,650,357,'客户提供的专利及体系认证展示','Patent and system certification display supplied by the client')+'</figure><div class="certification-copy reveal">'+label('专利与体系认证','PATENTS & SYSTEM CERTIFICATION')+title('让每一份用心，<br>有据可循。','A commitment<br>built on solid foundations.')+p('1,000 多项产品专利，是持续研发的积累。质量与环境管理体系，则将对品质的要求，落实到产品诞生的每一个环节。','More than 1,000 product patents reflect ongoing research and development. Quality and environmental management systems bring that same commitment to each stage of production.')+p('从关键部件检查到整椅测试，以系统化流程支持稳定的产品品质。','From component inspection to assembled-chair testing, systematic processes support consistent product quality.','body-copy')+'</div></section>'
 body+='<section class="global-section section-pad" id="global"><div class="global-visual" data-globe><img class="globe-fallback" aria-hidden="true" src="/assets/expertise-globe.svg?v=2" width="720" height="720" loading="lazy" alt=""><canvas class="globe-canvas" width="720" height="720" aria-hidden="true"></canvas><button class="globe-toggle" type="button" aria-label="暂停地球动画 / Pause globe animation" aria-pressed="false" hidden><svg viewBox="0 0 20 20" aria-hidden="true"><g class="globe-pause"><path d="M7 5v10M13 5v10"/></g><path class="globe-play" d="m7 4 9 6-9 6Z"/></svg></button><span class="global-coordinate" aria-hidden="true">RHYVIA · CONNECTED BY COMFORT</span></div><div class="global-copy reveal">'+label('全球布局','A GLOBAL REACH')+title('让舒适，<br>走进更广阔的世界。','Comfort, with<br>a world of possibility.')+p('依托 CBD 的全球网络，将研发、产品与服务连接起来，让舒适跨越地域，走进更多人的日常。','Drawing on CBD’s global network, we connect research, products and service to bring comfort into more everyday lives.')+'<div class="global-stats"><div><strong>28</strong>'+p('个国家及地区','Countries & regions','stat-label')+'</div><div><strong>'+bi('span','600万<span>+</span>','6M<span>+</span>')+'</strong>'+p('服务家庭','Households served','stat-label')+'</div></div>'+button('开启你的 RHYVIA 体验','Begin your RHYVIA experience','/experience/')+'</div></section>'
 return body
